from typing import List

def solution(board: List[List[str]]) -> List[List[str]]:
    b = [row[:] for row in board]
    R, C = len(b), len(b[0])
    for r in range(R):                      # push right
        write = C - 1
        for c in range(C - 1, -1, -1):
            if b[r][c] == '*':
                write = c - 1
            elif b[r][c] == '#':
                b[r][c] = '.'
                b[r][write] = '#'
                write -= 1
    for c in range(C):                      # push down
        write = R - 1
        for r in range(R - 1, -1, -1):
            if b[r][c] == '*':
                write = r - 1
            elif b[r][c] == '#':
                b[r][c] = '.'
                b[write][c] = '#'
                write -= 1
    return b
